INSERT OR IGNORE INTO ARTICULOS_ORIGINALES (ID, URL, TITULO, DESCRIPCION, URL_IMAGEN, FECHA, CONTENIDO, CATEGORIA) VALUES (
  'https://actualidad.rt.com/actualidad/587813-hallan-fosa-clandestina-seis-cuerpos', 'https://actualidad.rt.com/actualidad/587813-hallan-fosa-clandestina-seis-cuerpos', 'Hallan fosa clandestina con varios cuerpos en México que llevaba años sin ser descubierta', 'La Fiscalía General del Estado de Tabasco informó este miércoles del hallazgo de una fosa clandestina con seis cuerpos en un predio del municipio de Paraíso, en el sureste del país. El descubrimiento fue realizado por peritos forenses en coordinación con la Comisión Estatal de Búsqueda, y las autori...', 'https://mfes.b37m.ru/actualidad/public_images/2026.02/original/69964ffde9ff7133685a86f8.jpg', '2026-02-18T23:49:17Z', 'La Fiscalía General del Estado de Tabasco informó este miércoles del hallazgo de una fosa clandestina con seis cuerpos en un predio del municipio de Paraíso, en el sureste del país. El descubrimiento fue realizado por peritos forenses en coordinación con la Comisión Estatal de Búsqueda, y las autoridades estiman que los restos tendrían una antigüedad de entre 3 y 5 años, por lo que ya trabajan en su identificación.

El sitio tendría una extensión aproximada de 75 metros y se investiga si el hallazgo está relacionado con otra fosa localizada el 10 de febrero en la misma zona, aunque hasta el momento no se ha confirmado si se trata del mismo lugar. El caso se produce en un contexto de violencia persistente en el estado, donde se han registrado homicidios y otros hechos de alto impacto en los últimos meses.

⚪Comunicado. La #FGET y la Comisión Estatal de Búsqueda trabajan de manera conjunta en el municipio de Paraíso. pic.twitter.com/ZHr37JsEYK', 'Nacional'
);
